// #5a3976 (ee489910) — TC-AD-04: empty "מיקום העבודה" → "חובה למלא את השדה" under the city field, nothing under "רחוב". Never publishes.
import assert from 'node:assert/strict';
import { startDriver, byText, goTab, IS_IOS } from '../lib/session.js';

const ERR = 'חובה למלא את השדה';

describe('Job ad form: city required message placement #5a3976 @ios @android @prod-safe', function () {
  let d;
  before(async () => { d = await startDriver(); });
  after(async () => {
    if (!d) return;
    // leave the form without publishing
    await (IS_IOS ? (await byText(d, 'פרופיל')).click() : d.back()).catch(() => {});
    await d.deleteSession();
  });

  const rect = async (el) => el.getElementRect(el.elementId);
  const errorsY = async () => {
    const els = IS_IOS ? await d.$$(`-ios predicate string:label == "${ERR}"`) : await d.$$(`//*[@text="${ERR}"]`);
    const ys = [];
    for (const e of els) if (await e.isDisplayed().catch(() => false)) ys.push((await rect(e)).y);
    return ys;
  };

  it('TC-AD-04: city cleared → error directly under "מיקום העבודה", no error under "רחוב", form not published', async () => {
    await goTab(d, 'פרסם');
    await (await byText(d, 'מודעת דרוש עובד/שירות')).click();
    await (await byText(d, 'פרסום מודעת דרושים')).waitForDisplayed({ timeout: 10000 });

    await (await byText(d, '✕')).click();                 // clear the city pre-filled from the profile
    await (await byText(d, 'בחר עיר', true)).waitForDisplayed({ timeout: 5000 });

    const publish = await byText(d, 'פרסם מודעה');
    await publish.scrollIntoView?.().catch(() => {});
    await publish.click();

    // bring the city block back into view
    const cityLabel = await byText(d, 'מיקום העבודה', true);
    await cityLabel.scrollIntoView?.().catch(() => {});
    await cityLabel.waitForDisplayed({ timeout: 5000 });
    const streetLabel = await byText(d, 'רחוב');
    await streetLabel.waitForDisplayed({ timeout: 5000 });
    const payLabel = await byText(d, 'תשלום');

    const cityY = (await rect(cityLabel)).y;
    const streetY = (await rect(streetLabel)).y;
    const payY = await payLabel.isDisplayed().catch(() => false) ? (await rect(payLabel)).y : Infinity;
    const ys = await errorsY();

    const underCity = ys.filter((y) => y > cityY && y < streetY);
    const underStreet = ys.filter((y) => y > streetY && y < payY);
    assert.equal(underCity.length, 1, `exactly one "${ERR}" between "מיקום העבודה" and "רחוב", got ${underCity.length} (all: ${ys})`);
    assert.equal(underStreet.length, 0, `no "${ERR}" under "רחוב", got ${underStreet.length}`);

    // still on the form — nothing was published
    await (await byText(d, 'פרסום מודעת דרושים')).waitForDisplayed({ timeout: 3000 });
  });
});
